using System;using System.IO;using System.Net;using System.Net.Sockets;using System.Text;using System.Threading;using System.Diagnostics;using System.Reflection;using System.Collections.Generic;using System.Web.Script.Serialization;
class DeskHub {
 static JavaScriptSerializer json { get { return new JavaScriptSerializer(); } }static string folder,address="",token="";static object gate=new object();static TcpListener listener;
 static Dictionary<string,object> Obj(string s){return json.Deserialize<Dictionary<string,object>>(s);}
 static string Text(Dictionary<string,object> d,string k){return d.ContainsKey(k)?Convert.ToString(d[k]):"";}
 static string ReadBounded(Stream stream){using(var reader=new StreamReader(stream)){var b=new char[4096];var s=new StringBuilder();int n;while((n=reader.Read(b,0,b.Length))>0){if(s.Length+n>262144)throw new Exception("Response too large");s.Append(b,0,n);}return s.ToString();}}
 static string Remote(string path,object body,string secret){if(!path.StartsWith("/api/")||path.Contains("..")||path.Contains("#")||path.Contains("?"))throw new Exception("Invalid API path");var u=new Uri(address+path);var req=(HttpWebRequest)WebRequest.Create(u);req.AllowAutoRedirect=false;req.Proxy=null;req.Timeout=30000;req.ReadWriteTimeout=30000;req.Method=body==null?"GET":"POST";if(secret!="")req.Headers["Authorization"]="Bearer "+secret;if(body!=null){byte[] b=Encoding.UTF8.GetBytes(json.Serialize(body));req.ContentType="application/json";req.ContentLength=b.Length;using(var w=req.GetRequestStream())w.Write(b,0,b.Length);}try{using(var r=req.GetResponse())return ReadBounded(r.GetResponseStream());}catch(WebException e){if(e.Response!=null){using(var r=e.Response)throw new Exception(ReadBounded(r.GetResponseStream()));}throw;}}
 static object Native(string op,Dictionary<string,object> d){if(op=="pcHealth"){bool book=false,model=false;try{string f=Path.GetFullPath(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"../../output/ocr-link-token"));var r=(HttpWebRequest)WebRequest.Create("http://127.0.0.1:8765/v1/health");r.Proxy=null;r.AllowAutoRedirect=false;r.Timeout=2000;r.Headers["Authorization"]="Bearer "+File.ReadAllText(f).Trim();using(var v=r.GetResponse()){book=Text(Obj(ReadBounded(v.GetResponseStream())),"status")=="ready";}}catch{}try{var r=(HttpWebRequest)WebRequest.Create("http://127.0.0.1:8770/health");r.Proxy=null;r.AllowAutoRedirect=false;r.Timeout=4000;using(var v=r.GetResponse()){var d2=Obj(ReadBounded(v.GetResponseStream()));model=d2.ContainsKey("model_ready")&&Convert.ToBoolean(d2["model_ready"]);}}catch{}return new{book_ready=book,model_ready=model};}if(op=="paper"){string path=Text(d,"path");if(path!="/health"&&path!="/labels"&&path!="/classify")throw new Exception("Invalid paper endpoint");var req=(HttpWebRequest)WebRequest.Create("http://127.0.0.1:8770"+path);req.Proxy=null;req.AllowAutoRedirect=false;req.Timeout=150000;object body=d.ContainsKey("body")?d["body"]:null;if(body!=null){req.Method="POST";req.ContentType="application/json";byte[] data=Encoding.UTF8.GetBytes(json.Serialize(body));req.ContentLength=data.Length;using(var w=req.GetRequestStream())w.Write(data,0,data.Length);}using(var response=req.GetResponse())return json.DeserializeObject(ReadBounded(response.GetResponseStream()));}lock(gate){if(op=="config")return new{address=address,paired=token!=""};if(op=="pair"){var u=new Uri(Text(d,"address"));if((u.Scheme!="http"&&u.Scheme!="https")||u.UserInfo!=""||u.AbsolutePath!="/"||u.Query!=""||u.Fragment!="")throw new Exception("请输入网关根地址");var oldAddress=address;address=u.GetLeftPart(UriPartial.Authority);Dictionary<string,object> result;try{result=Obj(Remote("/api/pair",new{code=Text(d,"code")},""));}catch{address=oldAddress;throw;}if(!result.ContainsKey("token")){address=oldAddress;throw new Exception("配对失败");}token=Text(result,"token");var encrypted=System.Security.Cryptography.ProtectedData.Protect(Encoding.UTF8.GetBytes(token),null,System.Security.Cryptography.DataProtectionScope.CurrentUser);File.WriteAllText(Path.Combine(folder,"connection.json"),json.Serialize(new{address=address,token=Convert.ToBase64String(encrypted)}));return new{address=address,paired=true};}if(op=="request"){if(address=="")throw new Exception("请先配置网关地址");object body=d.ContainsKey("body")?d["body"]:null;return json.DeserializeObject(Remote(Text(d,"path"),body,token));}if(op=="export"){var file=Path.Combine(folder,"events-"+DateTime.Now.ToString("yyyyMMdd-HHmmss")+".json");File.WriteAllText(file,Text(d,"text"),Encoding.UTF8);return new{saved=file};}throw new Exception("Unknown operation");}}
 static void Serve(object state){using(var client=(TcpClient)state){client.ReceiveTimeout=150000;client.SendTimeout=150000;try{var stream=client.GetStream();var header=new List<byte>();int b;while(header.Count<16384&&(b=stream.ReadByte())>=0){header.Add((byte)b);int n=header.Count;if(n>=4&&header[n-4]==13&&header[n-3]==10&&header[n-2]==13&&header[n-1]==10)break;}string[] lines=Encoding.ASCII.GetString(header.ToArray()).Split(new[]{"\r\n"},StringSplitOptions.None);string[] first=lines[0].Split(' ');int length=0;bool origin=false;string host="";foreach(var l in lines){if(l.StartsWith("Content-Length:",StringComparison.OrdinalIgnoreCase))length=int.Parse(l.Substring(15));if(l.StartsWith("Origin:",StringComparison.OrdinalIgnoreCase))origin=l.Substring(7).Trim()!="http://127.0.0.1:"+((IPEndPoint)listener.LocalEndpoint).Port;if(l.StartsWith("Host:",StringComparison.OrdinalIgnoreCase))host=l.Substring(5).Trim();}if(length<0||length>8*1024*1024||origin||host!="127.0.0.1:"+((IPEndPoint)listener.LocalEndpoint).Port)throw new Exception("Rejected request");var body=new byte[length];for(int n=0;n<length;){int count=stream.Read(body,n,length-n);if(count==0)throw new IOException();n+=count;}byte[] response;string type="application/json; charset=utf-8",status="200 OK";try{if(first[1].StartsWith("/native/")&&first[0]=="POST"){response=Encoding.UTF8.GetBytes(json.Serialize(Native(first[1].Substring(8),Obj(Encoding.UTF8.GetString(body)))));}else if(first[0]=="GET"){string name=first[1]=="/"?"index.html":first[1].TrimStart('/');if(name!="index.html"&&name!="app.js"&&name!="style.css")throw new Exception("Not found");using(var r=Assembly.GetExecutingAssembly().GetManifestResourceStream(name))using(var m=new MemoryStream()){r.CopyTo(m);response=m.ToArray();}type=name.EndsWith("js")?"text/javascript":name.EndsWith("css")?"text/css":"text/html; charset=utf-8";}else throw new Exception("Method denied");}catch(Exception e){status="400 Bad Request";response=Encoding.UTF8.GetBytes(json.Serialize(new{error=e.Message}));}byte[] h=Encoding.ASCII.GetBytes("HTTP/1.1 "+status+"\r\nContent-Type: "+type+"\r\nContent-Length: "+response.Length+"\r\nConnection: close\r\nCache-Control: no-store\r\nX-Content-Type-Options: nosniff\r\n\r\n");stream.Write(h,0,h.Length);stream.Write(response,0,response.Length);}catch{}}}
 [STAThread]static void Main(string[] args){folder=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"AmdDeskHub");bool headless=Array.IndexOf(args,"--headless")>=0;int pos=Array.IndexOf(args,"--data-dir");if(pos>=0&&pos+1<args.Length)folder=Path.GetFullPath(args[pos+1]);Directory.CreateDirectory(folder);try{var c=Obj(File.ReadAllText(Path.Combine(folder,"connection.json")));address=Text(c,"address");token=Encoding.UTF8.GetString(System.Security.Cryptography.ProtectedData.Unprotect(Convert.FromBase64String(Text(c,"token")),null,System.Security.Cryptography.DataProtectionScope.CurrentUser));}catch{}int port=0;try{port=new Uri(Text(Obj(File.ReadAllText(Path.Combine(folder,"running.json"))),"url")).Port;}catch{}int pi=Array.IndexOf(args,"--port");if(pi>=0&&pi+1<args.Length)port=int.Parse(args[pi+1]);if(port<0||port>65535)throw new Exception("Invalid port");listener=new TcpListener(IPAddress.Loopback,port);try{listener.Start();}catch(SocketException){listener=new TcpListener(IPAddress.Loopback,0);listener.Start();}string url="http://127.0.0.1:"+((IPEndPoint)listener.LocalEndpoint).Port+"/";File.WriteAllText(Path.Combine(folder,"running.json"),json.Serialize(new{url=url,pid=Process.GetCurrentProcess().Id}));new Thread(()=>{for(;;){try{ThreadPool.QueueUserWorkItem(Serve,listener.AcceptTcpClient());}catch{break;}}}){IsBackground=true}.Start();if(headless){Thread.Sleep(Timeout.Infinite);return;}var tray=new System.Windows.Forms.NotifyIcon();tray.Icon=System.Drawing.SystemIcons.Application;tray.Text="智阅学习助手";tray.Visible=true;var menu=new System.Windows.Forms.ContextMenu();menu.MenuItems.Add("打开控制台",(s,e)=>Process.Start(url));menu.MenuItems.Add("退出",(s,e)=>System.Windows.Forms.Application.Exit());tray.ContextMenu=menu;tray.DoubleClick+=(s,e)=>Process.Start(url);Process.Start(url);System.Windows.Forms.Application.Run();tray.Dispose();listener.Stop();}
}
